import {prettyKey,sentenceTitle,fieldMatches,same} from './schema-form.js';
import {flatten,fieldsFor,pagesFor,initialize,valueOf,setValue,applyChoice,resetValue,regionChoice,meterMix,moveBoundary,setMix,changedFields,sliderFor,fieldAt,visiblePages,changePace} from './guided-model.js';

const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>Number(v.toFixed(3)).toLocaleString('en-US',{maximumFractionDigits:3});
const glyphs={home:'M3 11 12 3l9 8M5 10v11h14V10M9 21v-8h6v8',electric:'m14 2-9 12h6l-1 8 9-13h-6z',water:'M12 2C10 6 4 11 4 15a8 8 0 0 0 16 0c0-4-6-9-8-13ZM8 15c0 2 1 3 3 4',gas:'M13 2c2 6-5 7-2 12 1-3 3-3 4-6 7 7 5 14-3 14C2 22 1 13 7 8c-1 5 1 6 2 7-2-6 4-8 4-13Z',meter:'M4 4h16v16H4zM7 13a5 5 0 0 1 10 0M12 13l3-4M8 17h8',network:'M4 4h5v5H4zM15 15h5v5h-5zM4 15h5v5H4zM6 9v6M9 6h8v9M9 17h6',sun:'M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10M12 1v3M12 20v3M1 12h3M20 12h3M4 4l2 2M18 18l2 2M4 20l2-2M18 6l2-2',check:'m5 12 4 5L20 5',crew:'M7 9a3 3 0 1 0 0-6 3 3 0 0 0 0 6M2 21v-7a5 5 0 0 1 10 0v7M16 4l4 4-8 8-4-4z',manual:'M6 3h12v18H6zM9 7h6M9 11h6M9 15h4',ami:'M9 18h6v4H9zM12 18v-6M8 13a6 6 0 0 1 8 0M5 9a10 10 0 0 1 14 0M2 5a15 15 0 0 1 20 0'};
function icon(name){return `<span class="gw-medallion" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linejoin="round" stroke-linecap="round"><path d="${glyphs[name]||glyphs.network}"/></svg></span>`;}
const observers=new WeakMap();
const sectionIcon={Start:'electric',Place:'home',Homes:'home',Climate:'sun',Networks:'network',Meters:'meter','Studio operations':'crew','Studio year':'manual',Review:'check'};
function choiceButton(id,label,caption,selected,kind='network',extra=''){return `<button type="button" class="gw-choice ${selected?'selected':''}" data-choice="${esc(id)}" aria-pressed="${!!selected}" ${extra}>${icon(kind)}<strong>${esc(label)}</strong>${caption?`<small>${esc(caption)}</small>`:''}<span class="gw-check" aria-hidden="true">${selected?'✓':''}</span></button>`;}

export function installGuidedSetup({root,data,draft,local,onSave,onLibrary,onAgent,onMetrics,onFinish,onRetry,error='',focus=true}){
 observers.get(root)?.disconnect();
 if(!data?.wizard){root.innerHTML=`<section class="gw-loading"><h1>Building your setup…</h1><p role="status">${esc(error||'Loading the engine’s configuration catalogue.')}</p>${error?'<button id="gw-retry">Retry</button>':''}<button id="gw-library">My simulations</button></section>`;root.querySelector('#gw-retry')?.addEventListener('click',onRetry);root.querySelector('#gw-library').onclick=onLibrary;return;}
 const state=initialize(draft,data,{local}),fields=fieldsFor(data,draft),pages=pagesFor(data,fields),visible=visiblePages(pages,state,data.wizard),page=pages.find(p=>p.id===state.page)||visible[0];
 state.page=page.id;const position=visible.findIndex(p=>p.id===page.id),pinned=id=>Object.keys(state.pins).some(k=>state.pins[k]&&(k===id||k.startsWith(id+'.')));
 let working=false;
 const save=(dirty=true)=>{if(dirty){draft.configDirty=true;state.review=null;}onSave(draft);};
 const message=(text,isError=false)=>{const el=root.querySelector('#setup-message');el.textContent=text;el.classList.toggle('gw-error',isError);};
 const invalid=()=>{const bad=root.querySelector('[aria-invalid="true"]');if(bad){bad.focus();message('Fix the highlighted value before leaving this page.',true);}return !!bad;};
 const redraw=(focus=false)=>installGuidedSetup({root,data,draft,local,onSave,onLibrary,onAgent,onMetrics,onFinish,onRetry,error,focus});
 const go=id=>{if(invalid()||working)return;state.page=id;save(false);redraw(true);};
 function fieldMarkup(f,parent=null){
  const value=valueOf(draft,data,f),title=f.id==='town:town.houses'&&state.mode==='studio'&&draft.execution==='local'?'Homes across the utility':sentenceTitle(f.title),rail=sliderFor({...f,window:data.wizard.sliders?.[f.id]},value),disabled=f.disabled?'disabled':'';
  if(f.children)return `<fieldset class="gw-compound"><legend>${esc(title)}</legend><p>${esc(f.description)}</p><div class="gw-fields">${f.children.map(c=>fieldMarkup({...c,scope:f.scope,id:f.id+'.'+c.key,path:f.path+'.'+c.key,disabled:f.disabled||c.disabled},f)).join('')}</div></fieldset>`;
  const status=parent?.reason||f.reason,help=f.scope==='world'?'Affects the saved world’s daily simulation.':f.impact||parent?.impact||f.description;
  let control='';
  if(f.type==='boolean')control=`<div class="gw-toggle" role="group" aria-label="${esc(title)}">${[true,false].map(v=>`<button type="button" data-set="${esc(f.id)}" data-bool="${v}" aria-pressed="${v===value}" ${disabled}>${v?'On':'Off'}</button>`).join('')}</div>`;
  else if(f.type==='enum')control=`<div class="gw-toggle" role="group" aria-label="${esc(title)}">${f.options.map(v=>`<button type="button" data-set="${esc(f.id)}" data-option="${esc(v)}" aria-pressed="${v===value}" ${disabled}>${esc(prettyKey(v))}</button>`).join('')}</div>`;
  else if(f.type==='set')control=`<div class="gw-choices gw-services">${f.options.map(v=>choiceButton(v,({electric:'Electric',water:'Water',gas:'Gas'})[v]||prettyKey(v),'',value?.includes(v),v,`data-service="${esc(v)}" data-field="${esc(f.id)}" ${disabled}`)).join('')}</div>`;
  else if(rail)control=`<div class="gw-slider-top"><output data-output="${esc(f.id)}">${num(value*rail.scale)}<small>${esc(rail.suffix)}</small></output></div><input class="gw-range" aria-label="${esc(title)}" data-range="${esc(f.id)}" type="range" min="${rail.min}" max="${rail.max}" step="${rail.step}" value="${value*rail.scale}" data-scale="${rail.scale}" ${disabled}><div class="gw-limits"><span>${num(rail.min)} ${esc(rail.suffix)}</span><span>Drag to refine</span><span>${num(rail.max)} ${esc(rail.suffix)}</span></div><details class="gw-exact"><summary>Exact value</summary><label>${esc(title)} ${esc(f.unit||'')}<input aria-label="${esc(title)} exact value" type="number" step="any" data-input="${esc(f.id)}" value="${value}" ${disabled}></label>${rail.scale===100?'<small>Exact fraction: 0.25 = 25%.</small>':''}</details>`;
  else control=f.type==='json'?`<label class="gw-json">Structured values<textarea aria-label="${esc(title)}" data-input="${esc(f.id)}" rows="3" ${disabled}>${esc(JSON.stringify(value,null,2))}</textarea></label>`:`<input aria-label="${esc(title)}" data-input="${esc(f.id)}" type="${['number','integer'].includes(f.type)?'number':'text'}" step="any" value="${esc(value)}" ${disabled}>`;
  return `<article class="gw-field ${f.disabled?'gw-disabled':''}" data-card="${esc(f.id)}"><div class="gw-field-heading"><h3>${esc(title)}</h3><span class="gw-pin" data-pin="${esc(f.id)}">${pinned(f.id)?'Tuned':''}</span></div>${control}${status?`<p class="gw-status">${esc(status)}</p>`:''}<div class="gw-field-footer"><details><summary>What this changes</summary><p>${esc(help)}</p><p>${esc(f.description||parent?.description||'')}</p><small>${esc(f.id)}</small></details><button type="button" class="gw-text" data-reset="${esc(f.id)}" ${disabled}>${Object.hasOwn(state.suggestions,f.id)?'Use preset':'Reset'}</button></div><p class="gw-field-error" role="alert"></p></article>`;
 }
 function identity(){return `<h2>How would you like to set up?</h2><div class="gw-choices gw-pace-choices">${choiceButton('quick','Quick setup','Essentials · defaults for the rest',state.pace==='quick','electric','data-pace="quick"')}${choiceButton('full','Full setup','Every setting · at your own pace',state.pace==='full','network','data-pace="full"')}</div><p class="gw-note">${state.pace==='quick'?'Choose services, town size, region, and meter mix, then review. The remaining settings keep their starting values or your earlier adjustments.':'Shape every detail, or review at any time.'} Switch paths whenever you like; your choices stay.</p><div class="gw-identity"><label>Utility name<input id="gw-name" maxlength="100" value="${esc(draft.name)}"></label><label>What are you exploring? <small>Optional</small><textarea id="gw-purpose" maxlength="500" rows="2" placeholder="A growing town, older mains, a move to smart meters…">${esc(draft.purpose)}</textarea></label></div><h2>Choose your simulation</h2><div class="gw-choices">${choiceButton('world','Living world','Geography · meters · daily history',state.mode==='world','network',`data-mode="world" ${local?'':'disabled'}`)}${choiceButton('studio','Studio year','Operations · service · financial results',state.mode==='studio','manual','data-mode="studio"')}</div><p class="gw-note">${state.mode==='world'?'Create a saved physical world directly. It models daily consumption, meter deterioration, and physical events; it does not run billing or enterprise workflows.':'Configure the existing Studio year. It uses separate reading, operations, billing, and customer-service models. It is not the Virtual Systems enterprise simulation.'}${!local?' Saved physical worlds are available when opened from the desktop app.':''}</p><div class="gw-alternatives"><button class="gw-text" id="gw-metrics">Start from existing metrics</button><button class="gw-text" id="gw-agent">Talk through the setup</button></div>`;}
 function mixMarkup(){const mix=meterMix(draft,data);return `<div class="gw-choices gw-mix-presets">${[['manual','Manual-first','manual'],['mixed','Mixed','meter'],['ami','AMI-first','ami']].map(([id,label,i])=>choiceButton(id,label,'',state.mixChoice===id,i,`data-mix-choice="${id}"`)).join('')}</div><div class="gw-mix" aria-label="Reading route allocation"><div class="gw-mix-labels">${['AMI','AMR','Manual'].map((label,i)=>`<div class="mix-${i}"><strong>${label}</strong><output data-mix-value="${i}">${num(mix[i])}%</output></div>`).join('')}</div><div class="gw-mix-track"><i class="gw-mix-stem stem-0" aria-hidden="true"></i><i class="gw-mix-stem stem-1" aria-hidden="true"></i><div class="gw-mix-segments">${mix.map((v,i)=>`<span class="mix-${i}" data-segment="${i}" style="width:${v}%"></span>`).join('')}</div>${[0,1].map((n)=>`<input type="range" class="gw-mix-handle handle-${n}" data-boundary="${n}" aria-label="${n?'AMR–Manual boundary':'AMI–AMR boundary'}" min="0" max="100" step="1" value="${n?mix[0]+mix[1]:mix[0]}">`).join('')}</div><p class="gw-note">Drag the left circle to trade AMI and AMR. Drag the right circle to trade AMR and Manual. The total always stays at 100%.</p><details class="gw-exact"><summary>Enter exact percentages</summary><div class="gw-mix-exact">${['AMI','AMR','Manual'].map((label,i)=>`<label>${label} %<input type="number" min="0" max="100" step="any" data-mix-exact="${i}" value="${mix[i]}"></label>`).join('')}</div><button type="button" id="gw-apply-mix">Apply percentages</button><p id="gw-mix-error" role="alert"></p></details><button class="gw-text" type="button" id="gw-reset-mix">Use selected mix</button></div>`;}
 function reviewMarkup(){const changes=changedFields(draft,data,fields),activeIds=new Set(pages.filter(p=>!p.mode||p.mode===state.mode).flatMap(p=>p.fields.map(f=>f.id))),active=changes.filter(f=>activeIds.has(f.id)),dormant=changes.filter(f=>!activeIds.has(f.id));return `<div class="gw-review-hero">${icon('check')}<div><h2>${esc(draft.name)}</h2><p>${num(valueOf(draft,data,fields.find(f=>f.id==='town:town.houses')))} homes · ${esc(valueOf(draft,data,fields.find(f=>f.id==='town:customers_billing.services')).map(prettyKey).join(' / '))}</p><p>${state.mode==='world'?'Saved physical world':'Studio year'} · ${active.length} changed settings${state.pace==='quick'?' · Quick setup':''}</p></div></div><label class="gw-start-date">${state.mode==='world'?'World begins':'Open Studio at'}<input id="gw-date" type="date" value="${esc(draft.asOf||'2026-01-01')}" ${state.mode==='studio'?'min="2026-01-01" max="2026-12-31"':''}></label><p class="gw-note">${state.mode==='world'?'Creates a new world with fixed geography and an independent daily history. Studio year and map-day settings are retained in this setup but do not drive this world.':'Runs the Studio models using the reviewed town, annual settings, and existing scenario. Physical-world meter condition and daily-weather settings are retained but do not drive a Studio year.'}</p><div class="gw-review-list">${active.map(f=>`<button type="button" data-jump="${esc(pages.find(p=>p.fields.some(x=>x.id===f.id)).id)}"><span>${esc(sentenceTitle(f.title))}<small>${esc(f.scope==='world'?'Daily world':f.groupTitle)}</small></span><strong>${esc(typeof valueOf(draft,data,f)==='object'?JSON.stringify(valueOf(draft,data,f)):valueOf(draft,data,f))}</strong><span aria-hidden="true">↗</span></button>`).join('')||'<p>The engine’s starting values are selected.</p>'}</div>${dormant.length?`<details class="gw-dormant"><summary>${dormant.length} changed settings stored for the other simulation mode</summary><p>These will not affect this ${state.mode==='world'?'physical world':'Studio year'}.</p>${dormant.map(f=>`<button class="gw-text" type="button" data-jump="${esc(pages.find(p=>p.fields.some(x=>x.id===f.id)).id)}">${esc(sentenceTitle(f.title))}</button>`).join('')}</details>`:''}<p class="gw-note">${state.pace==='quick'?'Quick setup keeps the remaining engine defaults and any earlier custom values. Open full setup to inspect or refine them. ':''}${esc(data.wizard.note)}</p>${state.review?'<p class="gw-validated" role="status">Engine checks passed. Ready to create.</p>':''}`;}
 const region=page.kind==='region',selected=state.choices[page.id],choices=region?data.regions.map(r=>({...regionChoice(r),label:({great_lakes:'Great Lakes',upstate_suburban:'Northeast',midwest:'Midwest',warm_suburban:'Warm south'})[r.id]||r.name,caption:r.description})):page.id==='size'&&state.mode==='studio'&&draft.execution==='local'?[...(page.presets||[]),...[25000,50000,500000].map(n=>({id:'total-'+n,label:num(n),caption:'Homes across districts',values:{'town:town.houses':n}}))]:page.presets||[];
 root.innerHTML=`<div class="gw"><aside class="gw-rail"><div class="gw-brand"><span>UTILITY BUILDER</span><strong>A world of<br>your own.</strong><div class="gw-miniature" aria-hidden="true"><i class="gw-pipe p1"></i><i class="gw-pipe p2"></i><i class="gw-valve"></i><i class="gw-tower"></i></div></div><label class="gw-search-label">Find any setting<input type="search" id="gw-search" placeholder="Homes, leaks, AMI…" autocomplete="off"></label><div id="gw-search-results" aria-live="polite"></div><nav aria-label="Setup sections">${data.wizard.sections.map(section=>{const ps=visible.filter(p=>p.section===section);return ps.length?`<details ${page.section===section?'open':''}><summary>${icon(sectionIcon[section])}<span>${esc(section)}</span><small>${ps.length}</small></summary>${ps.map(p=>`<button type="button" data-jump="${esc(p.id)}" ${p.id===page.id?'aria-current="step"':''}>${esc(p.label)}</button>`).join('')}</details>`:'';}).join('')}</nav><button type="button" class="gw-pace-switch" id="gw-pace-switch">${state.pace==='quick'?'Open full setup':'Switch to quick setup'}</button><button type="button" class="gw-library" id="gw-library">My simulations</button><p class="gw-saved">Saved in this browser as you go.</p></aside><section class="gw-panel"><div class="gw-top"><span>${state.pace==='quick'?'Quick setup':esc(page.section)} <b>/</b> ${position<0?'Additional settings':`${position+1} of ${visible.length}`}</span><span class="gw-mode">${state.mode==='world'?'LIVING WORLD':'STUDIO YEAR'}</span></div><div class="gw-heading"><div><h1 tabindex="-1">${esc(page.title)}</h1>${page.note?`<p>${esc(page.note)}</p>`:''}</div>${icon(sectionIcon[page.section])}</div>${page.mode&&page.mode!==state.mode?`<p class="gw-mode-note">Stored for ${page.mode==='world'?'a physical world':'Studio only'}. These values do not affect the selected ${state.mode==='world'?'physical world':'Studio year'}.</p>`:''}<div class="gw-content">${page.kind==='identity'?identity():page.kind==='review'?reviewMarkup():page.kind==='mix'?mixMarkup():`${choices.length?`<div class="gw-choices">${choices.map((c,i)=>choiceButton(c.id,c.label,region?'':c.caption,selected===c.id&&Object.entries(c.values||{}).every(([id,v])=>{const f=fieldAt(fields,id);return !f||f.disabled||pinned(id)||same(valueOf(draft,data,f),v);}),region?'home':sectionIcon[page.section])).join('')}</div><p class="gw-preset-note">${esc(choices.find(c=>c.id===selected)?.caption||'Choose a starting point, then refine the values below.')} <span>Tuned values stay pinned.</span></p>`:''}${region?`<label class="gw-region-label">Service area <input id="gw-region" maxlength="200" value="${esc(draft.region)}"></label>`:''}${page.id==='size'?`<p class="gw-note">${state.mode==='studio'&&draft.execution==='local'?'Choose up to 500,000 homes. Studio processes them in districts of up to 10,000 homes; these environment settings repeat in every district. Analysts and contact staff are configured per district.':`One saved physical town supports up to ${num(data.homeLimit)} homes.${draft.totalHomes>data.homeLimit?' Your larger Studio total is retained separately; this world uses the town size shown below.':''}`}</p>`:''}<div class="gw-refine-heading"><h2>Fine-tune</h2><span>Drag a circle · or enter an exact value</span></div><div class="gw-fields">${page.fields.map(f=>fieldMarkup(f)).join('')}</div>`}</div><p id="setup-message" role="alert" tabindex="-1"></p><footer class="gw-actions"><button type="button" id="gw-back" ${position===0?'disabled':''}>Back</button><button type="button" class="gw-text" id="gw-review" ${page.kind==='review'?'hidden':''}>Review anytime</button><button type="button" class="gw-primary" id="gw-next">${page.kind==='review'?(state.review?(state.mode==='world'?'Create world':'Open Studio'):'Check setup'):'Continue'} <span aria-hidden="true">→</span></button></footer></section></div>`;
 root.querySelector('#gw-library').onclick=()=>{if(!invalid()){observers.get(root)?.disconnect();onLibrary();}};
 root.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>go(b.dataset.jump));
 root.querySelector('#gw-back').onclick=()=>go(position<0?'review':visible[Math.max(0,position-1)].id);
 root.querySelector('#gw-review').onclick=()=>go('review');
 root.querySelector('#gw-next').onclick=async()=>{if(invalid()||working)return;if(page.kind!=='review'){go(position<0?'review':visible[Math.min(visible.length-1,position+1)].id);return;}working=true;root.querySelectorAll('button,input,textarea,select').forEach(e=>e.disabled=true);message(state.review?'Creating your utility. Larger towns take longer; keep this page open.':'Checking all values with the engine…');try{const opened=await onFinish(draft,{create:!!state.review});if(opened)return;if(!state.review)state.review=true;save(false);redraw(false);}catch(e){redraw(false);const el=root.querySelector('#setup-message');el.textContent=e.message;el.classList.add('gw-error');el.focus();}finally{working=false;}};
 for(const [selector,key] of [['#gw-name','name'],['#gw-purpose','purpose'],['#gw-region','region'],['#gw-date','asOf']]){const input=root.querySelector(selector);if(input)input.oninput=()=>{const bad=(key==='name'&&!input.value.trim())||(key==='asOf'&&(!input.value||!input.validity.valid));input.setAttribute('aria-invalid',String(bad));draft[key]=input.value;save();};}
 root.querySelector('#gw-metrics')?.addEventListener('click',()=>{if(!invalid())onMetrics();});
 root.querySelector('#gw-agent')?.addEventListener('click',()=>{if(!invalid())onAgent();});
 const switchPace=pace=>{if(invalid())return;changePace(draft,pace,pages,data.wizard);save(false);redraw();};
 root.querySelectorAll('[data-pace]').forEach(b=>b.onclick=()=>switchPace(b.dataset.pace));
 root.querySelector('#gw-pace-switch').onclick=()=>switchPace(state.pace==='quick'?'full':'quick');
 root.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{state.mode=b.dataset.mode;save();redraw();});
 root.querySelectorAll('[data-choice]:not([data-mode]):not([data-pace]):not([data-service]):not([data-mix-choice])').forEach(b=>b.onclick=()=>{if(invalid())return;try{const choice=choices.find(c=>c.id===b.dataset.choice),skipped=applyChoice(draft,data,fields,page.id,choice);if(region)draft.region=data.regions.find(r=>r.id===choice.id).name;save();redraw();if(skipped.length)message(`${skipped.length} tuned values kept. Use “Use preset” beside a value to release it.`);}catch(e){message(e.message,true);}});
 function write(id,raw,input){try{setValue(draft,data,fields,id,raw);input?.setAttribute('aria-invalid','false');const card=input?.closest('.gw-field');if(card){card.querySelector('.gw-field-error').textContent='';card.querySelector('.gw-pin').textContent='Tuned';}save();return true;}catch(e){input?.setAttribute('aria-invalid','true');const error=input?.closest('.gw-field')?.querySelector('.gw-field-error');if(error)error.textContent=e.message;else message(e.message,true);return false;}}
 root.querySelectorAll('[data-input]').forEach(input=>input.oninput=()=>{if(write(input.dataset.input,input.value,input)){const card=input.closest('.gw-field'),range=card.querySelector('[data-range]');if(range){const scale=Number(range.dataset.scale),n=Number(input.value)*scale;range.min=Math.min(Number(range.min),n);range.max=Math.max(Number(range.max),n);range.value=n;card.querySelector('output').firstChild.textContent=num(n);}}});
 root.querySelectorAll('[data-range]').forEach(input=>input.oninput=()=>{const v=Number(input.value)/Number(input.dataset.scale);if(write(input.dataset.range,v,input)){const card=input.closest('.gw-field');card.querySelector('output').firstChild.textContent=num(Number(input.value));card.querySelector('[data-input]').value=v;}});
 root.querySelectorAll('[data-set]').forEach(b=>b.onclick=()=>{if(write(b.dataset.set,b.dataset.bool!==undefined?b.dataset.bool==='true':b.dataset.option,b))redraw();});
 root.querySelectorAll('[data-service]').forEach(b=>b.onclick=()=>{const f=fields.find(f=>f.id===b.dataset.field),current=valueOf(draft,data,f),next=current.includes(b.dataset.service)?current.filter(v=>v!==b.dataset.service):[...current,b.dataset.service];if(write(f.id,next,b))redraw();});
 root.querySelectorAll('[data-reset]').forEach(b=>b.onclick=()=>{try{resetValue(draft,data,fields,b.dataset.reset);save();redraw();}catch(e){message(e.message,true);}});
 const search=root.querySelector('#gw-search');search.oninput=()=>{const found=search.value.trim()?fields.filter(f=>fieldMatches(f,search.value)):[],box=root.querySelector('#gw-search-results');box.innerHTML=found.slice(0,25).map(f=>{const p=pages.find(p=>p.fields.some(x=>x.id===f.id));return `<button type="button" data-result="${esc(p.id)}">${esc(sentenceTitle(f.title))}<small>${esc(p.label)}${p.mode?' · '+p.mode:''}</small></button>`;}).join('')+(search.value.trim()?`<small>${found.length} matching settings${found.length>25?' · refine your search':''}</small>`:'');box.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>go(b.dataset.result));};
 if(page.kind==='mix'){
  const mixPresets={manual:[10,30,60],mixed:[40,40,20],ami:[80,15,5]};
  const paint=()=>{const mix=meterMix(draft,data);root.querySelectorAll('[data-mix-value]').forEach(e=>e.textContent=num(mix[Number(e.dataset.mixValue)])+'%');root.querySelectorAll('[data-segment]').forEach(e=>e.style.width=mix[Number(e.dataset.segment)]+'%');root.querySelectorAll('[data-mix-exact]').forEach(e=>e.value=mix[Number(e.dataset.mixExact)]);root.querySelectorAll('[data-boundary]').forEach(e=>{const n=Number(e.dataset.boundary),value=n?mix[0]+mix[1]:mix[0];e.value=value;e.setAttribute('aria-valuetext',`${num(mix[0])}% AMI, ${num(mix[1])}% AMR, ${num(mix[2])}% Manual`);});const track=root.querySelector('.gw-mix-track');track.classList.toggle('gw-close-handles',mix[1]/100*track.clientWidth<54);track.querySelectorAll('.gw-mix-stem').forEach((e,i)=>e.style.left=(17+(track.clientWidth-34)*(i?mix[0]+mix[1]:mix[0])/100)+'px');};
  const commit=mix=>{setMix(draft,data,fields,mix);state.mixChoice='custom';save();paint();root.querySelectorAll('[data-mix-choice]').forEach(b=>{b.classList.remove('selected');b.setAttribute('aria-pressed','false');b.querySelector('.gw-check').textContent='';});};
  root.querySelectorAll('[data-boundary]').forEach(input=>input.oninput=()=>commit(moveBoundary(meterMix(draft,data),Number(input.dataset.boundary),Number(input.value))));
  root.querySelectorAll('[data-mix-choice]').forEach(b=>b.onclick=()=>{setMix(draft,data,fields,mixPresets[b.dataset.mixChoice]);state.mixChoice=b.dataset.mixChoice;state.lastMix=b.dataset.mixChoice;save();redraw();});
  root.querySelector('#gw-reset-mix').onclick=()=>{setMix(draft,data,fields,mixPresets[state.lastMix]||[valueOf({},data,fields.find(f=>f.id==='town:ami.ami_route_share'))*100,valueOf({},data,fields.find(f=>f.id==='town:ami.amr_route_share'))*100,0].map((v,i,a)=>i===2?100-a[0]-a[1]:v));state.mixChoice=state.lastMix||'';save();redraw();};
  root.querySelectorAll('[data-mix-exact]').forEach(i=>i.oninput=()=>i.setAttribute('aria-invalid','true'));
  root.querySelector('#gw-apply-mix').onclick=()=>{try{const inputs=[...root.querySelectorAll('[data-mix-exact]')];if(inputs.some(i=>!i.value.trim()))throw Error('Enter all three percentages.');commit(inputs.map(i=>Number(i.value)));inputs.forEach(i=>i.setAttribute('aria-invalid','false'));root.querySelector('#gw-mix-error').textContent='';}catch(e){root.querySelector('#gw-mix-error').textContent=e.message;}};paint();const observer=new ResizeObserver(paint);observer.observe(root.querySelector('.gw-mix-track'));observers.set(root,observer);
 }
 if(focus)root.querySelector('h1').focus();
}

export function worldRequest(draft,data){
 const settings={...flatten(data.defaults.world),...flatten(draft.worldSettings)},worldSettings=Object.fromEntries(Object.entries(settings).map(([path,v])=>[path.split('.').at(-1),v]));
 const request={preset:draft.preset,townOverrides:draft.townOverrides,environment:draft.name.trim(),start:draft.asOf||'2026-01-01',worldSettings};
 const signature=JSON.stringify(request);if(draft.guidedSetup.commandSignature!==signature){draft.guidedSetup.commandId=crypto.randomUUID();draft.guidedSetup.commandSignature=signature;}
 return {commandId:draft.guidedSetup.commandId,...request};
}
